// 10k-row parse budget/perf check.
//
// Loads Tests/fixtures/blockpit_10k.csv (deterministic, generated by
// gen_blockpit_10k.cpp), parses it, and asserts:
//   * all 10,000 lines parse, none fail;
//   * formula ground truth (verified against an independent tally): every
//     currency is touched by exactly 2500 of the 10000 rows - 1000
//     purchases (+0.5, k=0/1), 500 withdrawals (-0.25), 500 earn (+0.1 into
//     balance AND bonus), 500 viban (+0.3 to-side) - so each currency
//     wallet ends at balance 500 - 125 + 50 + 150 = 575.0 and bonus 50.0;
//     the inner EUR wallet carries 2000 * (-30) = -60000.0;
//   * moneySpent per wallet, pinned by the verified first run (BTC/LUNA
//     77450, ETH 77500, CRO 77550, EUR -60000 - any drift is a core
//     regression);
//   * the parse wall clock stays under the CI-safe cap (a wide margin
//     below the app's 120 s JNI budget) - the measured time is printed.
//
// Build: tests target set (see CMakeLists.txt). ctest entry: big_fixture_10k.
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include "../Structs.h"
#include "../TransactionManager.h"
#include "../TransactionParser.h"
#include "../Wallet/Wallet.h"

static int g_checks = 0;
static int g_failures = 0;

#define CHECK(cond)                                                                 \
    do {                                                                            \
        ++g_checks;                                                                 \
        if (!(cond)) {                                                              \
            ++g_failures;                                                           \
            std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);             \
        }                                                                           \
    } while (0)

#define CHECK_NEAR(a, b, eps)                                                       \
    do {                                                                            \
        ++g_checks;                                                                 \
        double _a = (a), _b = (b);                                                  \
        if (_a + (eps) < _b || _a - (eps) > _b) {                                   \
            ++g_failures;                                                           \
            std::printf("FAIL %s:%d: %s (%f) !~ %s (%f)\n", __FILE__, __LINE__,     \
                        #a, _a, #b, _b);                                            \
        }                                                                           \
    } while (0)

int main() {
    const std::string path = std::filesystem::path(NF_TX_CORE_TEST_DATA_DIR) /
                             "blockpit_10k.csv";
    std::ifstream in(path);
    if (!in) {
        std::printf("FAIL: cannot open fixture %s\n", path.c_str());
        return 1;
    }
    std::vector<std::string> lines;
    std::string line;
    while (std::getline(in, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        lines.push_back(line);
    }
    CHECK(lines.size() == 10001);   // header + 10k data rows

    const auto t0 = std::chrono::steady_clock::now();
    TransactionParser parser(lines);
    parser.parseFromCsv(Mode::CDC);
    auto tm = std::make_unique<TransactionManager>();
    tm->setTransactions(parser.getTransactions(), Mode::CDC);
    tm->processTransactions();
    const auto t1 = std::chrono::steady_clock::now();
    const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0)
                        .count();
    std::printf("10k-row parse: %lld ms\n", static_cast<long long>(ms));

    CHECK(parser.getTransactions().size() == 10000);
    CHECK(parser.getFailedLines() == 0);

    const auto &w = tm->getWallets();
    CHECK(w.size() == 5);
    for (const char *cur: {"BTC", "ETH", "LUNA", "CRO"}) {
        if (w.count(cur) != 1) {
            std::printf("FAIL: missing wallet %s\n", cur);
            ++g_failures;
            continue;
        }
        // Lattice ground truth (gen_blockpit_10k.cpp): each currency sees
        // 1000 purchases, 500 withdrawals, 500 earn, 500 viban over the
        // 10000 rows.
        CHECK_NEAR((double) w.at(cur).getBalance(), 575.0, 1e-9);
        CHECK_NEAR((double) w.at(cur).getBonusBalance(), 50.0, 1e-9);
    }
    CHECK(w.count("EUR") == 1);
    CHECK_NEAR((double) w.at("EUR").getBalance(), -60000.0, 1e-9);

    // Money spent: pinned from the verified first run (regression net).
    // getMoneySpent() returns long double - printf's %f needs a double cast.
    static const char *EXPECTED_SPENT[5] = {"BTC", "ETH", "LUNA", "CRO", "EUR"};
    static const double SPENT[5] = {77450.0, 77500.0, 77450.0, 77550.0, -60000.0};
    for (int i = 0; i < 5; ++i) {
        const double spent = w.count(EXPECTED_SPENT[i])
                ? (double) w.at(EXPECTED_SPENT[i]).getMoneySpent() : 0.0;
        std::printf("  %s moneySpent = %.6f\n", EXPECTED_SPENT[i], spent);
        CHECK_NEAR(spent, SPENT[i], 1e-9);
    }

    // CI-safe runtime cap: 30 s is five times the budget headroom a real
    // 10k parse may consume before the app's 120 s JNI budget becomes a
    // concern; the expected order of magnitude is tens of milliseconds.
    CHECK(ms <= 30000);

    std::printf("\nbig_fixture_10k: %d checks, %d failure%s\n", g_checks,
                g_failures, g_failures == 1 ? "" : "s");
    return g_failures == 0 ? 0 : 1;
}
